(function(root){
const months=Array.from({length:12},(_,i)=>`2026-${String(i+1).padStart(2,'0')}`);
const partners=[{id:'f1',name:'Sund Dialog',type:'Face2face',kind:'maturity',rate:1500,advance:80,basis:'binding'},{id:'f2',name:'Kustens Säljteam',type:'Face2face',kind:'maturity',rate:1500,advance:80,basis:'binding'},{id:'b1',name:'Nordljus Rådgivning',type:'Företagsrådgivare',kind:'flat',rate:500,advance:0,basis:'binding'},{id:'b2',name:'Björk Energidialog',type:'Företagsrådgivare',kind:'flat',rate:650,advance:0,basis:'binding'},{id:'e1',name:'Lindgården Fastigheter',type:'Fastighetspartner',kind:'flat',rate:300,advance:0,basis:'active'},{id:'e2',name:'Ängsrum Bostäder',type:'Fastighetspartner',kind:'flat',rate:350,advance:0,basis:'active'}];
function addMonth(date,n){const d=new Date(date+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);return d.toISOString().slice(0,10)}
const orders=partners.flatMap((p,pi)=>months.flatMap((m,mi)=>Array.from({length:14+((mi*7+pi*3)%19)},(_,i)=>{const approved=m+'-'+String(3+i%20).padStart(2,'0');const binding=i%11===0?'':addMonth(approved,i%5===0?2:i%3===0?1:0);return {id:`DEMO-${p.id}-${mi+1}-${i+1}`,partner:p.id,approved,binding,active:binding?addMonth(binding,1):'',lost:i%11===0};})));
function baseline(p){return {id:`${p.id}-v1`,name:'Grundmodell 2026',from:'2026-01-01',to:'2026-12-31',kind:p.kind,rate:p.rate,advance:p.advance,basis:p.basis,status:'Granskad i demo'}}
function versions(p){return [{...baseline(p),to:'2026-06-30'},{...baseline(p),id:`${p.id}-v2`,name:'Ny nivå från juli',from:'2026-07-01',rate:p.rate*1.2,status:'Förslag'}]}
const validDate=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d).toISOString().slice(0,10)===d;
function validate(vs){if(!vs.length)throw Error('Minst en modellversion krävs.');if(vs.some(v=>v.kind!==vs[0].kind||v.basis!==vs[0].basis))throw Error('Använd samma modelltyp och kvalificeringsgrund inom en serie.');const sorted=[...vs].sort((a,b)=>a.from.localeCompare(b.from));for(let i=0;i<sorted.length;i++){const v=sorted[i];if(!validDate(v.from)||!validDate(v.to)||v.from>v.to)throw Error('Ange giltiga datum i stigande ordning.');if(!Number.isFinite(v.rate)||v.rate<0||!Number.isFinite(v.advance)||v.advance<0||v.advance>100)throw Error('Nivån måste vara minst 0 kr och förskottet 0–100 %.');if(!['flat','maturity'].includes(v.kind)||!['binding','active'].includes(v.basis))throw Error('Okänd modell eller kvalificeringsgrund.');if(i){const next=new Date(sorted[i-1].to+'T00:00:00Z');next.setUTCDate(next.getUTCDate()+1);if(next.toISOString().slice(0,10)!==v.from)throw Error('Giltighetsperioderna måste följa varandra utan luckor eller överlapp.');}}return sorted}
function calculate(input,vs,month){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('Ogiltig månad');validate(vs);const end=month+'-31',prev=month+'-01';const seen=new Map();let duplicate=0;for(const o of input){if(seen.has(o.id)){if(JSON.stringify(seen.get(o.id))!==JSON.stringify(o))throw Error('Motstridiga dubbletter: '+o.id);duplicate++;}else seen.set(o.id,o)}const rows=[...seen.values()];const groups=new Map(),items=[];let approved=0,qualified=0;for(const o of rows){if(!validDate(o.approved)|| (o.binding&&(!validDate(o.binding)||o.binding<o.approved))||(o.active&&(!validDate(o.active)||!o.binding||o.active<o.binding)))throw Error('Saknat eller felaktigt händelsedatum: '+o.id);if(o.approved>end)continue;if(o.approved.startsWith(month))approved++;
// Each order selects exactly one model. Maturity retains approval-date version;
// flat compensation uses its qualifying event date, including mid-month changes.
const matches=vs.filter(v=>{const d=v.kind==='maturity'?o.approved:o[v.basis];return d&&d>=v.from&&d<=v.to});if(matches.length>1)throw Error('Modellbyte ger dubbla kvalificeringsgrunder för '+o.id+'. Behåll modelltyp och datumgrund i en sammanhängande serie.');const v=matches[0];if(!v){if(o[vs[0].basis]&&o[vs[0].basis]<=end)throw Error('Ingen modell täcker avtalet '+o.id);continue}const event=o[v.basis];if(event&&event.startsWith(month))qualified++;
if(v.kind==='flat'){if(event&&event.startsWith(month))items.push({id:o.id,version:v.id,cohort:o.approved.slice(0,7),event,advance:0,extra:v.rate,amount:v.rate});continue;}
const key=o.approved.slice(0,7)+'|'+v.id;if(!groups.has(key))groups.set(key,{key,month:o.approved.slice(0,7),version:v.id,rate:v.rate,pct:v.advance,orders:[]});groups.get(key).orders.push(o);}
const cohorts=[...groups.values()].map(g=>{const v=vs.find(v=>v.id===g.version);const count=g.orders.length,advanceTotal=Math.round(count*g.rate*g.pct)/100;const before=g.orders.filter(o=>o[v.basis]&&o[v.basis]<prev).length,now=g.orders.filter(o=>o[v.basis]&&o[v.basis]<=end).length;const previousExtra=Math.max(0,before*g.rate-advanceTotal),extra=Math.max(0,now*g.rate-advanceTotal)-previousExtra,advance=g.month===month?advanceTotal:0;return {...g,count,before,now,advanceTotal,advance,extra,previousExtra,remaining:Math.max(0,advanceTotal-now*g.rate),amount:advance+extra}});
const advance=cohorts.reduce((s,g)=>s+g.advance,0),extra=cohorts.reduce((s,g)=>s+g.extra,0)+items.reduce((s,g)=>s+g.extra,0);return {month,approved,qualified,advance,extra,amount:Math.round((advance+extra)*100)/100,cohorts,items,duplicate};}
function snapshot(p,vs,m,input=orders.filter(o=>o.partner===p.id)){const report=calculate(input,vs,m);return JSON.parse(JSON.stringify({id:`DEMO-${p.id}-${m}`,partner:p.id,partnerName:p.name,month:m,lockedAt:'2026-07-03T09:00:00Z',versions:vs,orders:input.filter(o=>o.approved<=m+'-31').map(o=>({...o,binding:o.binding<=m+'-31'?o.binding:'',active:o.active<=m+'-31'?o.active:''})),report}));}
function initial(){const state={revision:0,versions:{},snapshots:{},localRates:{},audit:[]};partners.forEach(p=>{state.versions[p.id]=versions(p);state.localRates[p.id]=p.rate;months.slice(0,6).forEach(m=>state.snapshots[p.id+'|'+m]=snapshot(p,[baseline(p)],m));});return state;}
const api={months,partners,orders,baseline,versions,calculate,validate,snapshot,initial};if(typeof module!=='undefined')module.exports=api;else root.Model=api;
})(globalThis);
